using EduMark.Domain.Entities;
using Microsoft.EntityFrameworkCore;
namespace EduMark.Infrastructure.Persistence;
public static class DatabaseSeeder { public static async Task SeedAsync(EduMarkDbContext db, CancellationToken ct = default) { await db.Database.EnsureCreatedAsync(ct); if (await db.Courses.AnyAsync(ct)) return; db.Courses.AddRange(new Course { Title = "ASP.NET Core Microservices", Slug = "aspnet-core-microservices", Description = "Build resilient APIs with clean boundaries, EF Core and observability.", Price = 49, IsPublished = true }, new Course { Title = "Entity Framework Core in Practice", Slug = "entity-framework-core-in-practice", Description = "Model, query and persist relational data with production-minded patterns.", Price = 35, IsPublished = true }, new Course { Title = "Distributed Systems Foundations", Slug = "distributed-systems-foundations", Description = "Coming soon: messaging, idempotency and eventual consistency.", Price = 0, IsPublished = false }); await db.SaveChangesAsync(ct); } }
